function displayFireworks() {
	shaderTexture.shader(theShader);

	let data = serializeFirework();

	theShader.setUniform("resolution", [width, height]);
	theShader.setUniform("trailCount", data.trails.length);
	theShader.setUniform("trail", data.trails);
	theShader.setUniform("particleCount", data.particles.length);
	theShader.setUniform("particles", data.particles);
	theShader.setUniform("colors", data.colors);

	shaderTexture.rect(0, 0, width, height);
	texture(shaderTexture);

	rect(0, 0, width, height);

}

// Serializes and prepares all data so that it can be sent to the shader.
function serializeFirework() {
	data = {
		"trails": [],
		"particles": [],
		"colors": []
	};

	for (let trail of trails) {
		for (let pos of trail.positions) {
			data.trails.push(
				map(pos[0], 0, width, 0.0, 1.0),
				map(pos[1], 0, height, 1.0, 0.0));
		}

		colorMode(HSB, 255);
		let trailColor = color((trail.hue + 125) % 255, 255, 255);
		data.colors.push(red(trailColor) / 255.0, green(trailColor) / 255.0, blue(trailColor) / 255.0);
		colorMode(RGB, 255);

		for (let particle of trail.particles) {
			data.particles.push(
				map(particle.pos.x, 0, width, 0.0, 1.0),
				map(particle.pos.y, 0, height, 1.0, 0.0),
				min(particle.life * 0.01, 0.25))

			colorMode(HSB, 255);
			let itsColor = color(trail.hue, particle.sat, particle.bri);
			data.colors.push(red(itsColor), green(itsColor), blue(itsColor));
			colorMode(RGB, 255);
		}
	}
	return data;
}

// === Tab: trail.js ===
function Trail(x,y) {

	this.positions = [];
	this.particles = [];
	this.hue = globalHue;
	this.radius = TRAIL_MAX_RADIUS;
	this.speed = 6;
	this.lifetime = floor(random(40, 150));

	this.move = function() {
		this.lifetime--;
		if (this.lifetime > 0) {
			this.appendPositionToHead();
			this.trimTailPositions();
		} else if (this.lifetime == 0) {
			this.spawnParticles();
			this.positions = [];
		} else {
			//this.spawnParticles();
			this.moveParticles();
		}
	}

	/*
	this.get_position_by_time = function(time) {
		let angle = radians(time * this.speed);
		return {
			x: sin(angle) * this.radius + width / 2,
		  y: cos(angle) * this.radius + height / 2
		}
	}*/

	// Add position to trail.
	this.appendPositionToHead = function() {
		if (this.positions.length == 0) {
			this.positions.push([(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
		} else {
			let lastPos = this.positions[this.positions.length - 1];
			this.positions.push([lastPos[0] + map(noise(frameCount * 0.4), 0, 1, -1, 1), lastPos[1] - this.speed]);
		}
	}

	// Trim trail's tail if middle mouse is held and if it exceeds max count.
	this.trimTailPositions = function() {
		let removeCount = 1;
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == CENTER) {
			removeCount++;
		}

		for (let i = 0; i < removeCount; i++) {
			if (this.positions.length == 0) {
				break;
			}

			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) || this.positions.length > TRAIL_MAX_COUNT) {
				this.positions.splice(0, 1);
			}
		}
	}


	this.spawnParticles = function() {
		if (this.positions.length > 1 && this.particles.length < PARTICLE_MAX_COUNT) {
			let currentPos = this.positions[this.positions.length - 1]; //this.positions[this.positions.length-1];  //this.get_position_by_time(sketchTimer);
			//let lastPos = {x:(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),y:(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))}; //this.positions[this.positions.length-2]; //this.get_position_by_time(sketchTimer - 1);

			//let delta = new p5.Vector(lastPos.x, lastPos.y);
			//delta.sub(new p5.Vector(currentPos.x, currentPos.y));
			//delta.mult(PARTICLE_INITIAL_SPEED * random(PARTICLE_SPEED_VARIANCE));
			//print(currentPos);
			for (let i = 0; i<PARTICLE_MAX_COUNT;i++) {
				this.particles.push(new Particle(currentPos[0], currentPos[1], random(-15,15), random(-20,1)));
			}
		}
	}

	// Moves particles an iteration and kill particles that have no more life.
	this.moveParticles = function() {
		for (let i = this.particles.length - 1; i > -1; i--) {
			this.particles[i].move();
			if (this.particles[i].life <= 0) {
				this.particles.splice(i, 1);
			}
		}
	}

	// Serializes and prepares all data so that it can be sent to the shader.
	this.serialize = function() {
		data = {
			"trails": [],
			"particles": [],
			"colors": []
		};

		for (let pos of this.positions) {
			data.trails.push(
				map(pos[0], 0, width, 0.0, 1.0),
				map(pos[1], 0, height, 1.0, 0.0));
		}

		colorMode(HSB, 255);
		var trailColor = color((this.hue + 125) % 255, 255, 255);
		data.colors.push(red(trailColor) / 255.0, green(trailColor) / 255.0, blue(trailColor) / 255.0);
		colorMode(RGB, 255);

		for (let particle of this.particles) {
			data.particles.push(
				map(particle.pos.x, 0, width, 0.0, 1.0),
				map(particle.pos.y, 0, height, 1.0, 0.0),
				min(particle.life * 0.01, 0.25))

			colorMode(HSB, 255);
			var itsColor = color(this.hue, particle.sat, particle.bri);
			data.colors.push(red(itsColor), green(itsColor), blue(itsColor));
			colorMode(RGB, 255);
		}

		return data;
	}

	// Display it as a shader.
	this.display = function() {
		shaderTexture.shader(theShader);

		var data = this.serialize();

		theShader.setUniform("resolution", [width, height]);
		theShader.setUniform("trailCount", this.positions.length);
		theShader.setUniform("trail", data.trails);
		theShader.setUniform("particleCount", this.particles.length);
		theShader.setUniform("particles", data.particles);
		theShader.setUniform("colors", data.colors);

		shaderTexture.rect(0, 0, width, height);
		texture(shaderTexture);

		rect(0, 0, width, height);
	}

	// Display it as simple primitives.
	this.debugDisplay = function() {
		stroke(255, 0, 0);
		for (let particle of this.particles) {
			point(particle.pos.x, particle.pos.y);
		}

		stroke(255);
		for (let pos of this.positions) {
			point(pos[0], pos[1]);
		}
	}
}

// === Tab: particle.js ===
function Particle(x, y, vx, vy) {

	this.xOrig = x;
	this.pos = new p5.Vector(x, y);
	//this.spawnPos = this.pos;
	this.vel = new p5.Vector(vx, vy);
	this.vel.rotate(radians(random(-PARTICLE_SPAWN_ANGLE, PARTICLE_SPAWN_ANGLE)));
	this.airDrag = random(PARTICLE_MIN_AIR_DRAG, PARTICLE_MAX_AIR_DRAG);
	this.sat = random(255);
	this.bri = random(255);
	this.life = PARTICLE_LIFE;
	//print(this.pos);

	this.move = function() {

		// Pulls particles towards the center for an interesting effect.
		let pullForce = new p5.Vector(0, height);
		//pullForce.sub(this.pos);
		pullForce.mult(PARTICLE_PULL_FORCE);
		this.vel.add(pullForce);

		this.vel.mult(this.airDrag);

		this.pos.add(this.vel);

		this.life--;
	}
}


// === Tab: shader.js ===
let vertShader = `
	precision highp float;

	attribute vec3 aPosition;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`;

let fragShader = `
	precision highp float;

	uniform vec2 resolution;
	uniform int trailCount;
	uniform vec2 trail[${TRAIL_MAX_COUNT}];
	uniform int particleCount;
	uniform vec3 particles[${PARTICLE_MAX_COUNT}];
	uniform vec3 colors[${PARTICLE_MAX_COUNT}];

	void main() {
			vec2 st = gl_FragCoord.xy / resolution.xy;  // Warning! This is causing non-uniform scaling.

			float r = 0.0;
			float g = 0.0;
			float b = 0.0;
			float a = 1.0;

			for (int i = 0; i < ${TRAIL_MAX_COUNT}; i++) {
				if (i < trailCount) {
					vec2 trailPos = trail[i];

					float value = (float(i) / distance(st, trailPos.xy) * 0.00001)*3.0;  // Multiplier may need to be adjusted if max trail count is tweaked.

					r += colors[0].r * value;
					g += colors[0].g * value;
					b += colors[0].b * value;
				}
			}

			float mult = 0.000067;

			for (int i = 0; i < ${PARTICLE_MAX_COUNT}; i++) {
				if (i < particleCount) {
					vec3 particle = particles[i];
					vec2 pos = particle.xy;
					float mass = particle.z;
					vec3 color = colors[i + 1];

					r += color.r / distance(st, pos) * mult * mass * mass;
					g += color.g / distance(st, pos) * mult * mass * mass;
					b += color.b / distance(st, pos) * mult * mass * mass;
					a += a / distance(st, pos) * mult * mass * mass;
				}
			}

			gl_FragColor = vec4(r, g, b, a);
	}
`;

